-- =============================================================
-- Costmatic — catalog seed: Pakistan beverages (166 products)
--
-- Generated from pakistan_beverage_database.xlsx. NOT a migration: this is
-- catalog data, and migrations also run against staging and the second
-- client's project. Apply by hand, once:
--
--   psql "$DATABASE_URL" -f supabase/seeds/catalog_beverages_pakistan.sql
--
-- Safe to run twice — a product already in the catalog is skipped, never
-- duplicated.
--
-- ── Everything lands INACTIVE ───────────────────────────────
-- 166 SKUs is the whole Pakistani beverage market, not one shop's shelf. Every
-- row is inserted with is_active = false and no prices, so none of it reaches
-- the POS. The shopkeeper prices what they actually stock and ticks it active;
-- the rest stays out of the way but is there the day they take on the line.
--
-- ── Units ───────────────────────────────────────────────────
-- Stock is held in singles (bottle / can). Each product also gets the unit it
-- is BOUGHT in — shell, case or carton — with the real pieces-per-case from
-- the sheet, so one case of Pepsi 1.5L takes 6 bottles off the shelf.
--
-- Retail sells the single; wholesale sells the case. That split is set
-- explicitly here rather than left to the form's defaults.
-- =============================================================

-- ── Clear out the placeholder beverages seeded earlier ──────
-- Those were guesses from a WhatsApp list ("7Up Buddy", "Gourmet Jumbo").
-- They are superseded by the real catalog below. Only ever removes rows that
-- are still inactive and have never been traded — anything the shop has
-- actually sold, bought or counted is left exactly where it is.
do $cleanup$
declare v_removed int;
begin
  with doomed as (
    select p.id
    from products p
    where p.name_en in (
    'Gourmet Cola 1 Litre',
    'Gourmet Cola 1.5 Litre',
    'Gourmet Jumbo',
    'Gourmet Buddy',
    '7Up 1 Litre',
    '7Up 1.5 Litre',
    '7Up Jumbo',
    '7Up Buddy',
    '7Up Regular',
    'Sting Buddy',
    'Sting Regular',
    'Mountain Dew 1 Litre',
    'Mountain Dew 1.5 Litre',
    'Mountain Dew Jumbo',
    'Next Cola 1 Litre',
    'Next Cola 1.5 Litre',
    'Next Cola Jumbo',
    'Coca-Cola 1 Litre',
    'Coca-Cola 1.5 Litre',
    'Coca-Cola Jumbo',
    'Nestle Juice'
    )
      and p.is_active = false
      and not exists (select 1 from sale_items      si where si.product_id = p.id)
      and not exists (select 1 from purchase_items  pi where pi.product_id = p.id)
      and not exists (select 1 from stock_adjustments sa where sa.product_id = p.id)
      and coalesce((select s.quantity_in_base_unit from stock s where s.product_id = p.id), 0) = 0
  ), gone as (
    delete from products where id in (select id from doomed) returning 1
  )
  select count(*) into v_removed from gone;
  raise notice 'Placeholder beverages removed: %', v_removed;
end
$cleanup$;

