]},{"name":"Qarshi Springley 1.5 Litre PET Bottle","cat":"Water","company":"Qarshi Industries","brand":"Qarshi Springley","base":"bottle","units":[["bottle","1"],["case","6"]]},{"name":"Sufi 500ml / 1.5L PET Bottle","cat":"Water","company":"Local (Karachi-based)","brand":"Sufi","base":"bottle","units":[["bottle","1"],["case","24"]]},{"name":"Gourmet 500ml / 1.5L PET Bottle","cat":"Water","company":"Local (Karachi-based)","brand":"Gourmet","base":"bottle","units":[["bottle","1"],["case","24"]]},{"name":"Ismailia 500ml / 1.5L PET Bottle","cat":"Water","company":"Local","brand":"Ismailia","base":"bottle","units":[["bottle","1"],["case","24"]]},{"name":"Mai Kolachi 500ml / 1.5L PET Bottle","cat":"Water","company":"Local","brand":"Mai Kolachi","base":"bottle","units":[["bottle","1"],["case","24"]]},{"name":"Heritage 500ml / 1.5L PET Bottle","cat":"Water","company":"Local","brand":"Heritage","base":"bottle","units":[["bottle","1"],["case","24"]]},{"name":"Polar 500ml / 1.5L PET Bottle","cat":"Water","company":"Local","brand":"Polar","base":"bottle","units":[["bottle","1"],["case","24"]]},{"name":"Safa 500ml / 1.5L PET Bottle","cat":"Water","company":"Local","brand":"Safa","base":"bottle","units":[["bottle","1"],["case","24"]]},{"name":"Murree Sparkletts 500ml / 1.5L PET Bottle","cat":"Water","company":"Murree Brewery","brand":"Murree Sparkletts","base":"bottle","units":[["bottle","1"],["case","24"]]}]$json$::jsonb;
  v_it     jsonb;
  v_u      jsonb;
  v_pid    uuid;
  v_cat    uuid;
  v_parent uuid;
  v_base   text;
  v_new    int := 0;
  v_skip   int := 0;
begin
  -- Energy drinks did not exist as a category; file them with the other cold
  -- drinks rather than inventing a top-level heading for two SKUs.
  select id into v_parent from categories
   where name_en = 'Cold Drinks, Juices & Water' and parent_id is null limit 1;
  if v_parent is not null
     and not exists (select 1 from categories where name_en = 'Energy Drinks') then
    insert into categories (name_en, name_ur, parent_id, sort_order)
    values ('Energy Drinks', 'انرجی ڈرنکس', v_parent, 50);
  end if;

  for v_it in select * from jsonb_array_elements(v_items) loop
    if exists (select 1 from products where lower(name_en) = lower(v_it->>'name')) then
      v_skip := v_skip + 1;
      continue;
    end if;

    select id into v_cat from categories where name_en = v_it->>'cat' limit 1;
    v_base := v_it->>'base';

    insert into products (name_en, name_ur, category_id, company, brand,
                          base_unit, product_kind, min_stock_level, is_active)
    values (v_it->>'name', '', v_cat, v_it->>'company', v_it->>'brand',
            v_base, 'standard', 0, false)
    returning id into v_pid;

    insert into product_costs (product_id, cost_price) values (v_pid, 0)
      on conflict (product_id) do nothing;

    for v_u in select * from jsonb_array_elements(v_it->'units') loop
      insert into product_units (product_id, unit_name, factor,
                                 retail_price, wholesale_price,
                                 retail_eligible, wholesale_eligible)
      values (v_pid, v_u->>0, (v_u->>1)::numeric, 0, 0,
              -- the single is the counter sale; the case is the trade sale
              (v_u->>0) = v_base,
              (v_u->>0) <> v_base);
    end loop;

    insert into stock (product_id, quantity_in_base_unit) values (v_pid, 0)
      on conflict (product_id) do nothing;

    v_new := v_new + 1;
  end loop;

  raise notice 'Beverages: % added, % already present.', v_new, v_skip;
end
$bev$;
